#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maximumScore(vector<int>& nums, int k) {
        int i = k, j = k, minVal = nums[k], res = nums[k];
        int n = nums.size();
        while (i > 0 || j < n - 1) {
            if ((i > 0 ? nums[i - 1] : 0) > (j < n - 1 ? nums[j + 1] : 0))
                minVal = min(minVal, nums[--i]);
            else
                minVal = min(minVal, nums[++j]);
            res = max(res, minVal * (j - i + 1));
        }
        return res;
    }
};
